import {
  createResizablePanels,
  type PanelsOrientation,
  type ResizablePaneOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For, merge, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** One pane: the primitive's bounds plus what the skin puts inside it. */
export interface ResizablePane extends ResizablePaneOptions {
  /** The visible heading at the top of the pane; left out, the pane has no heading. */
  readonly title?: string | undefined;
  readonly children?: JSX.Element | undefined;
}

export interface ResizablePanelsProps {
  /** The panes, in order. Sizes are percentages of the group and always sum to 100. */
  readonly panes: ReadonlyArray<ResizablePane>;
  /** `vertical` puts the panes side by side; `horizontal` stacks them. @default "vertical" */
  readonly orientation?: PanelsOrientation | undefined;
  /** Controlled: the host owns the layout, and a new array is a new layout. */
  readonly sizes?: ReadonlyArray<number> | undefined;
  /** The uncontrolled start; ignored while `sizes` is set. */
  readonly defaultSizes?: ReadonlyArray<number> | undefined;
  /** Keyboard step, in percent. @default 10 */
  readonly step?: number | undefined;
  /** The group's accessible name. */
  readonly label?: string | undefined;
  /** Persist the layout in localStorage under this key (the host's namespace). */
  readonly storageKey?: string | undefined;
  /** A request to change the layout the host may ignore. */
  readonly onSizesChange?: ((sizes: ReadonlyArray<number>) => void) | undefined;
  /** The group's height in CSS, since a percentage layout needs one. @default "18rem" */
  readonly height?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_HEIGHT = "18rem";

// The frame: the group is a grid, the panes are surfaces on the page, and the bars are the tracks between them.
const groupClass = css.cn(
  css.display("grid"),
  css.width("100%"),
  css.boxSizing("border-box"),
  css.overflow("hidden"),
  css.padding(t.space._2),
  css.gap(t.space._1),
  css.bg(t.color.page),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.color(t.color.text),
  css.fontSize(t.font.size),
);

// The sizes are the primitive's percentages as grid fractions; a separator is an auto track of its own width. A layout
// change eases in only for a reader who allows motion, and never while the pointer is dragging the bar.
const groupMotion = css.cn(
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("grid-template-columns 160ms ease-out, grid-template-rows 160ms ease-out"),
  ),
  css.attr("data-resizing", "true")(css.transition("none")),
);

const paneClass = css.cn(
  css.boxSizing("border-box"),
  css.minWidth("0"),
  css.minHeight("0"),
  css.overflow("auto"),
  css.padding(t.space._3),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.lg),
  css.color(t.color.text),
);

const paneTitleClass = css.cn(
  css.margin("0"),
  css.marginBlockEnd(t.space._2),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("600"),
  css.letterSpacing("0.04em"),
  css.textTransform("uppercase"),
  css.color(t.color.muted),
);

// The bar is the focusable separator itself, not a button wrapped around one: its whole 12 px width is the target, and the
// grip inside it is the visible handle.
const separatorClass = css.cn(
  css.position("relative"),
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.boxSizing("border-box"),
  css.margin("0"),
  css.padding("0"),
  css.border("none"),
  css.borderRadius("999px"),
  css.bg("transparent"),
  css.outline("none"),
  css.touchAction("none"),
  css.userSelect("none"),
  css.group("resizable-separator"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(
    css.bg(t.color.buttonBackground),
    css.outline("2px solid", t.color.focusRing),
    css.outlineOffset("-2px"),
  ),
  css.attr("data-resizing", "true")(css.bg(t.color.buttonBackgroundPressed)),
);

const separatorVerticalClass = css.cn(
  css.width(t.space._3),
  css.height("100%"),
  css.cursor("col-resize"),
);

const separatorHorizontalClass = css.cn(
  css.width("100%"),
  css.height(t.space._3),
  css.cursor("row-resize"),
);

// The handle is a short line in the bar's middle; it is visible on hover, on keyboard focus and for the whole drag.
const gripClass = css.cn(
  css.display("block"),
  css.pointerEvents("none"),
  css.borderRadius("999px"),
  css.bg(t.color.borderHover),
  css.opacity("0"),
  css.within(css.hover, "resizable-separator")(css.opacity("1")),
  css.within(css.focusVisible, "resizable-separator")(css.opacity("1")),
  css.within(css.attr("data-resizing", "true"), "resizable-separator")(css.opacity("1")),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("opacity 120ms ease-out, background-color 120ms ease-out"),
  ),
);

const gripVerticalClass = css.cn(gripClass, css.width("2px"), css.height(t.space._5));
const gripHorizontalClass = css.cn(gripClass, css.height("2px"), css.width(t.space._5));

/** The primitive's percentages as a grid template; `auto` is the separator between each pair. */
const template = (sizes: ReadonlyArray<number>): string =>
  sizes.map((size, index) => (index < sizes.length - 1 ? `${size}fr auto` : `${size}fr`)).join(" ");

/**
 * A layout of panes with a resizable bar between each pair, styled: `createResizablePanels` owns the whole model — the
 * sizes in percent (always summing to 100), each pane's bounds, the focusable `role=separator` with its `aria-*`, the
 * arrows / Home / End / Enter keys, the pointer drag, collapse and restore, and `storageKey` persistence. The skin owns
 * the grid and the surfaces, paints the primitive's sizes as track fractions, and draws the grab handle, the focus ring
 * and the reduced-motion rules.
 *
 * The separator is the widget a keyboard reader reaches with Tab; it names the pane on its left (`aria-controls`) and
 * resizes that pane and its neighbour. A `collapsible` pane collapses to `collapsedSize` on Enter through the separator
 * before it and returns to the size it left.
 */
export const ResizablePanels = (props: ResizablePanelsProps): JSX.Element => {
  // The pane list carries the host's JSX. It is read once, here: reading it later (inside the primitive's own computation,
  // which asks for its options lazily) would create those components in an effect phase with no owner, and Solid 2's dev
  // build refuses that — `PRIMITIVE_IN_EFFECT_CALLBACK`, a throw in a real `vite dev` app that a production build hides.
  const panes = props.panes;
  const panels = createResizablePanels({
    // the primitive reads the options lazily; the skin's `title` and content are not part of them
    get panes() {
      return panes.map(({ title: _title, children: _children, ...pane }) => pane);
    },
    get orientation() {
      return props.orientation;
    },
    get sizes() {
      return props.sizes;
    },
    get defaultSizes() {
      return props.defaultSizes;
    },
    get step() {
      return props.step;
    },
    get label() {
      return props.label;
    },
    get storageKey() {
      return props.storageKey;
    },
    get onSizesChange() {
      return props.onSizesChange;
    },
  });

  const vertical = (): boolean => (props.orientation ?? "vertical") === "vertical";

  const layout = (): JSX.CSSProperties =>
    vertical()
      ? { "grid-template-columns": template(panels.sizes()) }
      : { "grid-template-rows": template(panels.sizes()) };

  const separator = (index: number) =>
    merge(panels.separatorProps(index), {
      "data-part": "resizable-panels-separator",
      get "data-orientation"() {
        return vertical() ? "vertical" : "horizontal";
      },
      get "data-resizing"() {
        return panels.resizing() === index ? "true" : "false";
      },
      get class() {
        return css.cn(
          separatorClass,
          vertical() ? separatorVerticalClass : separatorHorizontalClass,
        );
      },
    });

  return (
    <div
      {...panels.groupProps}
      data-part="resizable-panels"
      data-orientation={vertical() ? "vertical" : "horizontal"}
      data-resizing={panels.resizing() === null ? "false" : "true"}
      class={css.cn(groupClass, groupMotion, props.class)}
      style={{ ...layout(), height: props.height ?? DEFAULT_HEIGHT }}
    >
      <For each={panes}>
        {(pane, index) => (
          <>
            <div {...panels.paneProps(index())} data-part="resizable-panels-pane" class={paneClass}>
              <Show when={pane.title !== undefined}>
                <h3 class={paneTitleClass}>{pane.title}</h3>
              </Show>
              {pane.children}
            </div>
            <Show when={index() < panes.length - 1}>
              <div {...separator(index())}>
                <span
                  aria-hidden="true"
                  data-part="resizable-panels-grip"
                  class={vertical() ? gripVerticalClass : gripHorizontalClass}
                />
              </div>
            </Show>
          </>
        )}
      </For>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { For } from "solid-js";

import { ResizablePanels } from "./resizable-panels.tsx";

/** The demo's files: names are enough, nothing opens. */
export const PANEL_FILES = ["index.html", "styles.css", "app.tsx", "notes.md", "package.json"];

/** The middle pane's code, shown as written. */
export const PANEL_CODE = `export const App = () => (
  <ResizablePanels
    panes={[
      { title: "Files", min: 15, collapsible: true },
      { title: "Editor", min: 25 },
      { title: "Preview", min: 15 },
    ]}
  />
);`;

const fileStyle = {
  display: "block",
  width: "100%",
  padding: "2px 4px",
  border: "0",
  borderRadius: "4px",
  background: "transparent",
  color: "inherit",
  font: "inherit",
  textAlign: "start",
  cursor: "pointer",
} as const;

const file = (name: string): JSX.Element => (
  <button type="button" data-part="resizable-panels-file" style={fileStyle}>
    {name}
  </button>
);

const FilesPane = (): JSX.Element => (
  <div style={{ display: "grid", gap: "2px" }}>
    <For each={PANEL_FILES}>{file}</For>
  </div>
);

const EditorPane = (): JSX.Element => (
  <pre
    style={{
      margin: "0",
      "font-family": "ui-monospace, SFMono-Regular, Menlo, monospace",
      "font-size": "0.75rem",
      "line-height": "1.6",
      "white-space": "pre-wrap",
    }}
  >
    {PANEL_CODE}
  </pre>
);

const PreviewPane = (): JSX.Element => (
  <div
    style={{
      display: "grid",
      "place-items": "center",
      height: "100%",
      "min-height": "6rem",
      "border-radius": "6px",
      background: "linear-gradient(135deg, #d9e6f2, #8aa9c9)",
      color: "#1f3242",
      "font-size": "0.75rem",
    }}
  >
    index.html
  </div>
);

/**
 * The starter in ordinary use: a Files / Editor / Preview workspace. The middle pane is the flexible one, the side panes
 * have minimums, and the first one folds away with Enter. The sentence under it is the whole keyboard contract.
 */
export const ResizablePanelsExample = (props: {
  readonly class?: string | undefined;
}): JSX.Element => (
  <div class="demo-column">
    <ResizablePanels
      class={props.class}
      label="Workspace layout"
      defaultSizes={[22, 50, 28]}
      panes={[
        { title: "Files", label: "Files", min: 15, collapsible: true, children: <FilesPane /> },
        { title: "Editor", label: "Editor", min: 25, children: <EditorPane /> },
        { title: "Preview", label: "Preview", min: 15, children: <PreviewPane /> },
      ]}
    />
    <p class="demo-text">
      Drag a divider to resize a pane, or focus it and use the arrow keys; Home and End jump to the
      bounds, and Enter folds the Files pane away.
    </p>
  </div>
);

/** What a mounted demo hands the test: where it lives and a teardown. */
export interface MountedResizablePanels {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/** The demo's width, so a percent step is a whole number of pixels and the drag math is the same in every test run. */
const DEMO_WIDTH = 600;

/** Mounts the styled layout at 600 px, the width the fixture's drag tests measure against. */
export const mountResizablePanels = (): MountedResizablePanels => {
  const root = document.createElement("div");
  root.style.width = `${DEMO_WIDTH}px`;
  document.body.append(root);
  const dispose = render(() => <ResizablePanelsExample />, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { type MountedResizablePanels, mountResizablePanels } from "./resizable-panels.fixture";

// @cssints/headless checks `createResizablePanels` against specs/patterns/resizable-panels.qnt, the APG scenarios and the
// differential walk. This file is the skin's oracle: it mounts the starter in a real Chromium and drives the separator a
// reader does, reading the states the primitive announces and the grid the skin paints from them.

/** Solid applies setters on the next flush; two frames let the measured layout settle. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** A layout change eases over 160 ms for a reader who allows motion: wait it out before measuring a pane. */
const settleMotion = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 200));

/** Polls until `done` holds, so a transition is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const live: MountedResizablePanels[] = [];

const mounted = (): MountedResizablePanels => {
  const instance = mountResizablePanels();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`resizable-panels: no ${selector}`);
  }
  return element;
};

const group = (root: ParentNode): HTMLElement => required(root, '[data-part="resizable-panels"]');

const panes = (root: ParentNode): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="resizable-panels-pane"]'),
];

const separators = (root: ParentNode): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="resizable-panels-separator"]'),
];

const grip = (separator: Element): HTMLElement =>
  required(separator, '[data-part="resizable-panels-grip"]');

const value = (separator: HTMLElement): number => Number(separator.getAttribute("aria-valuenow"));

const template = (root: ParentNode): string => group(root).style.gridTemplateColumns;

const press = async (target: HTMLElement, key: string): Promise<void> => {
  target.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await frame();
};

/** The pointer of a drag, as the primitive's handlers receive it: a real `PointerEvent` with the mouse's coordinates. */
const pointer = (
  element: HTMLElement,
  type: string,
  position: { readonly x: number; readonly y: number },
  buttons: number,
): void => {
  element.dispatchEvent(
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      pointerId: 1,
      pointerType: "mouse",
      isPrimary: true,
      button: 0,
      buttons,
      clientX: position.x,
      clientY: position.y,
    }),
  );
};

const centre = (element: HTMLElement): { readonly x: number; readonly y: number } => {
  const box = element.getBoundingClientRect();
  return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
};

describe("ResizablePanels", () => {
  it("is a named group of three panes with a focusable separator between each pair", async () => {
    const { root } = mounted();
    await frame();

    expect(group(root).getAttribute("role")).toBe("group");
    expect(group(root).getAttribute("aria-label")).toBe("Workspace layout");
    expect(panes(root)).toHaveLength(3);
    expect(separators(root)).toHaveLength(2);

    const [first, second] = separators(root);
    if (first === undefined || second === undefined) {
      throw new Error("resizable-panels: missing separator");
    }

    for (const [index, separator] of [first, second].entries()) {
      expect(separator.getAttribute("role")).toBe("separator");
      expect(separator.getAttribute("aria-orientation")).toBe("vertical");
      expect(separator.tabIndex).toBe(0);
      expect(separator.getAttribute("aria-controls")).toBe(panes(root)[index]?.id);
      expect(separator.getAttribute("aria-valuemin")).toBe(index === 0 ? "15" : "25");
      expect(separator.getAttribute("aria-valuemax")).toBe("80");
      expect(grip(separator).getAttribute("aria-hidden")).toBe("true");
    }

    expect(value(first)).toBe(22);
    expect(value(second)).toBe(50);
    // the skin paints the primitive's sizes as the grid's fractions, with the bars as their own tracks
    expect(template(root)).toBe("22fr auto 50fr auto 28fr");
    // the panes are surfaces with a border, the bars are the focused widgets
    expect(getComputedStyle(panes(root)[0] as HTMLElement).borderTopStyle).toBe("solid");
  });

  it("reaches both separators with Tab, and the handle shows on focus", async () => {
    const { root } = mounted();
    await frame();

    const files = [
      ...root.querySelectorAll<HTMLButtonElement>('[data-part="resizable-panels-file"]'),
    ];
    const last = files.at(-1);
    if (last === undefined) {
      throw new Error("resizable-panels: no file");
    }
    last.focus();
    await userEvent.keyboard("{Tab}");
    await frame();

    const [first] = separators(root);
    if (first === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    expect(document.activeElement).toBe(first);
    expect(getComputedStyle(first).outlineStyle).toBe("solid");
    // the grip is the visible handle: it is drawn while the bar has keyboard focus
    await waitFor(() => getComputedStyle(grip(first)).opacity === "1");
  });

  it("moves the boundary by the step with the arrow keys and stops at the minimum", async () => {
    const { root } = mounted();
    await frame();
    const [first] = separators(root);
    if (first === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    first.focus();
    const startWidth = panes(root)[0]?.getBoundingClientRect().width ?? 0;

    await press(first, "ArrowRight");
    expect(value(first)).toBe(32);
    expect(template(root)).toBe("32fr auto 40fr auto 28fr");

    await settleMotion();
    const wider = panes(root)[0]?.getBoundingClientRect().width ?? 0;
    expect(wider).toBeGreaterThan(startWidth);

    await press(first, "ArrowLeft");
    expect(value(first)).toBe(22);

    // the pane never shrinks under its 15% minimum, and its neighbour keeps its own 25%
    for (let step = 0; step < 4; step += 1) {
      await press(first, "ArrowLeft");
    }
    expect(value(first)).toBe(15);
    expect(template(root)).toBe("15fr auto 57fr auto 28fr");
  });

  it("jumps the pair to its bounds with Home and End", async () => {
    const { root } = mounted();
    await frame();
    const [first] = separators(root);
    if (first === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    first.focus();

    await press(first, "Home");
    expect(value(first)).toBe(15);
    expect(template(root)).toBe("15fr auto 57fr auto 28fr");

    await press(first, "End");
    expect(value(first)).toBe(47);
    // End stops where the right pane of the pair reaches its 25% minimum, not at the left pane's 80%
    expect(template(root)).toBe("47fr auto 25fr auto 28fr");
  });

  it("collapses the first pane on Enter and restores the size it left", async () => {
    const { root } = mounted();
    await frame();
    const [first] = separators(root);
    if (first === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    first.focus();

    await press(first, "Enter");
    expect(value(first)).toBe(0);
    expect(template(root)).toBe("0fr auto 72fr auto 28fr");

    await press(first, "Enter");
    expect(value(first)).toBe(22);
    expect(template(root)).toBe("22fr auto 50fr auto 28fr");
  });

  it("drags the boundary by the pointer's distance, and the layout follows the pointer", async () => {
    const { root } = mounted();
    await frame();
    const [first] = separators(root);
    if (first === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    const width = group(root).getBoundingClientRect().width;
    const start = centre(first);
    const step = (width * 10) / 100;

    pointer(first, "pointerdown", start, 1);
    pointer(first, "pointermove", { x: start.x + step, y: start.y }, 1);
    await frame();

    expect(value(first)).toBe(32);
    expect(template(root)).toBe("32fr auto 40fr auto 28fr");
    expect(group(root).getAttribute("data-resizing")).toBe("true");

    pointer(first, "pointermove", { x: start.x - step, y: start.y }, 1);
    await frame();
    // the pointer went past the pane's 15% minimum: the layout stops there, not at the pointer
    expect(value(first)).toBe(15);
    expect(template(root)).toBe("15fr auto 57fr auto 28fr");

    pointer(first, "pointerup", { x: start.x - step, y: start.y }, 0);
    await frame();
    expect(group(root).getAttribute("data-resizing")).toBe("false");
  });

  it("moves only its own pair from the second separator of three panes", async () => {
    const { root } = mounted();
    await frame();
    const [first, second] = separators(root);
    if (first === undefined || second === undefined) {
      throw new Error("resizable-panels: missing separator");
    }
    second.focus();

    await press(second, "ArrowRight");
    expect(value(second)).toBe(60);
    expect(value(first)).toBe(22);
    expect(template(root)).toBe("22fr auto 60fr auto 18fr");

    // the pane on the right stops at its 15% minimum, not at the group's end
    for (let step = 0; step < 3; step += 1) {
      await press(second, "ArrowRight");
    }
    expect(value(second)).toBe(63);
    expect(template(root)).toBe("22fr auto 63fr auto 15fr");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
